# Synthetic regression probe for vllm-42188 (renders the real examples/tool_chat_template_gemma4.jinja)
from pathlib import Path

import jinja2.sandbox
import pytest

TEMPLATE_PATH = Path(__file__).resolve().parent.parent.parent / "examples" / "tool_chat_template_gemma4.jinja"


@pytest.fixture(scope="module")
def tmpl():
    return jinja2.sandbox.ImmutableSandboxedEnvironment().from_string(TEMPLATE_PATH.read_text())


def _assistant_with_call():
    return {
        "role": "assistant",
        "content": "",
        "tool_calls": [
            {"id": "call_B", "type": "function",
             "function": {"name": "get_weather", "arguments": {"city": "SF"}}}
        ],
    }


@pytest.mark.parametrize(
    "tool_msg",
    [
        {"role": "tool", "tool_call_id": "call_A", "content": "sunny"},
        {"role": "tool", "content": "sunny"},
        {"role": "tool", "name": None, "tool_call_id": None, "content": "sunny"},
    ],
    ids=["mismatched_id", "no_id_no_name", "explicit_none"],
)
def test_openai_tool_message_without_resolvable_name(tmpl, tool_msg):
    msgs = [{"role": "user", "content": "hi"}, _assistant_with_call(), tool_msg]
    out = tmpl.render(messages=msgs, bos_token="<bos>", add_generation_prompt=True)
    assert "response:unknown{" in out
    assert "sunny" in out


def test_legacy_tool_responses_with_none_name(tmpl):
    msg = _assistant_with_call()
    msg["tool_responses"] = [{"name": None, "response": {"temperature": 20}}]
    out = tmpl.render(messages=[{"role": "user", "content": "hi"}, msg], bos_token="<bos>")
    assert "response:unknown{" in out


def test_matching_id_still_resolves_name(tmpl):
    msgs = [{"role": "user", "content": "hi"}, _assistant_with_call(),
            {"role": "tool", "tool_call_id": "call_B", "content": "sunny"}]
    out = tmpl.render(messages=msgs, bos_token="<bos>", add_generation_prompt=True)
    assert "response:get_weather{" in out
